import{_ as l,c as i,o as e,a3 as t}from"./chunks/framework.BurWKwwG.js";const b=JSON.parse('{"title":"数据访问","description":"","frontmatter":{},"headers":[],"relativePath":"zh/2.3_access.md","filePath":"zh/2.3_access.md"}'),r={name:"zh/2.3_access.md"};function s(n,a,o,c,h,d){return e(),i("div",null,a[0]||(a[0]=[t('<h1 id="数据访问" tabindex="-1">数据访问 <a class="header-anchor" href="#数据访问" aria-label="Permalink to “数据访问”">​</a></h1><p>CBD3 提供多种方式来访问和下载结直肠癌生物标志物数据。</p><h2 id="访问方式" tabindex="-1">访问方式 <a class="header-anchor" href="#访问方式" aria-label="Permalink to “访问方式”">​</a></h2><h3 id="web-界面" tabindex="-1">Web 界面 <a class="header-anchor" href="#web-界面" aria-label="Permalink to “Web 界面”">​</a></h3><p>CBD3 的 Web 界面提供以下功能模块：</p><ul><li><strong>Biomarker 浏览</strong>：浏览和搜索整理的结直肠癌生物标志物数据库，支持分页表格浏览</li><li><strong>Explore（探索）</strong>： <ul><li>Gene Expression Atlas：基于 UMAP 的单细胞基因表达可视化，支持选择 Dataset、Cell Type 和基因表达叠加</li><li>Protein Interaction：基于 Cytoscape.js 的 PPI 蛋白质互作网络浏览</li></ul></li><li><strong>Single-Cell Analyses（单细胞分析）</strong>：7 个分析模块 <ul><li>DEGs：差异表达基因分析（火山图 + 表格）</li><li>KEGG Pathway：KEGG 通路富集气泡图</li><li>Ridge Ranking：Ridge 排名图</li><li>Trajectory：轨迹分析与伪时间分析</li><li>CellChat：细胞通讯网络分析</li><li>Network Sensitivity：网络敏感性分析</li><li>Predictive Ability：ROC 预测能力分析</li></ul></li><li><strong>Clinical（临床分析）</strong>： <ul><li>Survival：Kaplan-Meier 生存曲线分析</li><li>Immune：免疫浸润热力图</li></ul></li><li><strong>Download</strong>：数据下载页面</li><li><strong>Submit</strong>：数据提交页面</li></ul><h3 id="api-访问" tabindex="-1">API 访问 <a class="header-anchor" href="#api-访问" aria-label="Permalink to “API 访问”">​</a></h3><ul class="contains-task-list"><li><strong>RESTful API</strong>：对 CBD3 数据的程序化访问</li><li class="task-list-item enabled"><input class="task-list-item-checkbox" type="checkbox" id="task-item-9201309"><label class="task-list-item-label" for="task-item-9201309"> API 文档正在建设中</label></li></ul><h2 id="访问级别" tabindex="-1">访问级别 <a class="header-anchor" href="#访问级别" aria-label="Permalink to “访问级别”">​</a></h2><ul><li><strong>无需注册</strong>：所有功能均可免费使用，无需注册</li></ul><h2 id="数据使用协议" tabindex="-1">数据使用协议 <a class="header-anchor" href="#数据使用协议" aria-label="Permalink to “数据使用协议”">​</a></h2><ul><li><strong>研究目的</strong>：学术和非营利研究</li><li><strong>教育用途</strong>：教学和学习活动</li><li><strong>个人分析</strong>：个人研究和学习</li></ul><h2 id="数据引用" tabindex="-1">数据引用 <a class="header-anchor" href="#数据引用" aria-label="Permalink to “数据引用”">​</a></h2><h3 id="引用要求" tabindex="-1">引用要求 <a class="header-anchor" href="#引用要求" aria-label="Permalink to “引用要求”">​</a></h3><p>使用 CBD3 数据时，请引用：</p><ol><li><strong>CBD3 数据库</strong>：引用数据库本身</li><li><strong>原始来源</strong>：适用时引用主要数据来源</li></ol>',16)]))}const _=l(r,[["render",s]]);export{b as __pageData,_ as default};
